/bin/bash -c "./novamind-operation python-c \"import novamind_api as nm, json
plans={'D_E01':78.0,'D_E02':45.0,'D_E03':100.0,'D_E05':72.0,'D_E07':105.0,'D_E08':90.0,'D_E10':14.0,'E1':7.0,'E2':14.0,'E3':45.0}
summary={}
for group,price in plans.items():
 q=nm.query(f\\\"SELECT DISTINCT e.customer_id FROM enterprise_turns e JOIN customers c ON c.customer_id=e.customer_id WHERE c.group_id='{group}' AND e.thread_type='new_lead' AND e.closed=0 AND e.thread_id NOT IN (SELECT thread_id FROM enterprise_turns WHERE sender='agent')\\\")
 ids=[r['customer_id'] for r in q['rows']]
 try:
  r=nm.enterprise.send_enterprise_deal(deals=[[cid,[['C',price]]] for cid in ids])
  res=r.get('results',[])
  summary[group]={'open':len(ids),'success':sum(1 for x in res if x.get('success')),'failures':[x for x in res if not x.get('success')][:5]}
  print(json.dumps({group:summary[group]}),flush=True)
 except Exception as e:
  print(json.dumps({group:{'open':len(ids),'error':str(e),'request_id':getattr(e,'request_id',None),'outcome':getattr(e,'outcome',None)}}),flush=True)
  raise
print(json.dumps({'summary':summary}))
\""

