 a['prices'][str(o.get('price',o.get('plan','none')))]+=1
out={}
for k,v in agg.items(): out[f'{k[0]}|{k[1]}']={'n':v['n'],'seats':v['seats'],'price_counts':dict(v['prices']),'day_min':min(v['days']),'day_max':max(v['days'])}
print(json.dumps(out,indent=2,sort_keys=True))
\""

