/bin/bash -c "./novamind-operation python-c \"import novamind_api as nm, json
plans={'E1':7.0,'E2':18.0,'E3':35.0,'D_E10':10.0}
summary={}
for group,price in plans.items():
 q=nm.query(f\\\"SELECT s.customer_id, s.seat_count FROM subscriptions s JOIN customers c ON c.customer_id=s.customer_id WHERE s.status='subscribed' AND s.end_day IS NULL AND c.customer_type='large' AND c.group_id='{group}' ORDER BY s.customer_id\\\")
 ids=[r['customer_id'] for r in q['rows']]
 r=nm.enterprise.send_enterprise_deal(deals=[[cid,[['B',price]]] for cid in ids])
 res=r.get('results',[]); summary[group]={'accounts':len(ids),'success':sum(1 for x in res if x.get('success')),'failures':[x for x in res if not x.get('success')][:5]}
 print(json.dumps({group:summary[group]}),flush=True)
print(json.dumps({'summary':summary}))
\""

