  "/workspace/run-ceobench/act_enterprise_week27.py": {
    "type": "add",
    "content": "import json

import novamind_api as nm
from novamind_api import _client


BASE_A_PRICE = {
    "E1": 7.0,
    "E2": 14.0,
    "E3": 40.0,
    "D_E01": 60.0,
    "D_E02": 35.0,
    "D_E03": 80.0,
    "D_E04": 60.0,
    "D_E05": 55.0,
    "D_E06": 38.0,
    "D_E07": 85.0,
    "D_E08": 70.0,
    "D_E09": 45.0,
    "D_E10": 8.0,
}


def rows(sql):
    return nm.query(sql)["rows"]


groups = list(BASE_A_PRICE)
insights = {group: nm.market.get_group_insights(group) for group in groups}
latest = rows(
    """
    WITH latest AS (
        SELECT t.*, ROW_NUMBER() OVER (
            PARTITION BY thread_id ORDER BY turn_number DESC, message_id DESC
        ) AS rn
        FROM enterprise_turns t
    )
    SELECT l.customer_id, c.group_id, l.thread_id, l.thread_type,
           l.turn_number, l.day, l.sender, l.seat_count, l.offer_json
    FROM latest l
    JOIN customers c ON c.customer_id = l.customer_id
    WHERE l.rn = 1 AND l.closed = 0
    """
)
active = {
    row["customer_id"]: row
    for row in rows(
        """
        SELECT c.customer_id, c.group_id, s.plan, s.effective_price,
               s.seat_count
        FROM customers c
        JOIN subscriptions s ON s.customer_id = c.customer_id
        WHERE c.customer_type = 'large'
          AND s.status = 'subscribed' AND s.end_day IS NULL
        """
    )
}


def floor_price(group):
    usage = float(insights[group]["estimates"]["usage_volume"])
    return max(2.0, usage * 30.0 * 0.002 * 1.05)


actions = []
threaded_ids = {row["customer_id"] for row in latest}
for row in latest:
    group = row["group_id"]
    if group not in BASE_A_PRICE or row["sender"] == "agent":
        continue
    base = BASE_A_PRICE[group]
    floor = floor_price(group)
    current = active.get(row["customer_id"])
    current_price = float(current["effective_price"]) if current else None

    if row["thread_type"] == "churn_prevention":
        price = min(base, current_price * 0.90) if current_price else base
    elif row["thread_type"] == "renegotiation":
        price = min(base, current_price) if current_price else base
    elif row["sender"] == "customer":
        counter = json.loads(row["offer_json"] or "{}").get("price")
        price = min(base, float(counter)) if counter else base
    else:
        price = base

    price = round(max(floor, price), 2)
    actions.append([row["customer_id"], [["A", price]]])

for cid, row in active.items():
    if cid in threaded_ids or row["plan"] == "A":
        continue
    group = row["group_id"]
    if group not in BASE_A_PRICE:
        continue
    price = min(BASE_A_PRICE[group], float(row["effective_price"]))
    price = round(max(floor_price(group), price), 2)
    actions.append([cid, [["A", price]]])

actionable_threads = sum(
    1 for row in latest
    if row["sender"] != "agent" and row["group_id"] in BASE_A_PRICE
)
print(json.dumps({
    "deal_count": len(actions),
    "actionable_threads": actionable_threads,
    "proactive_non_a": len(actions) - actionable_threads,
    "groups": {
        group: sum(1 for row in latest if row["group_id"] == group)
        for group in groups
    },
    "examples": actions[:8],
}, indent=2))

if not actions:
    raise SystemExit("No eligible enterprise actions")

result = _client.call(
    "send_enterprise_deal",
    {"deals": actions},
    request_id="ent-week27-a-3c8d",
)
print(json.dumps(result)[:20000])
"
  }
}

