import json

from novamind_api import _client


def call(name, args, request_id, limit=1200):
    result = _client.call(name, args, request_id=request_id)
    print(request_id, name, json.dumps(result)[:limit])


call(
    "set_targeted_ad_spend",
    {
        "targeted_spend": {
            "content_marketing": {
                "S2": 150000.0,
                "D_S04": 75000.0,
                "D_S09": 40000.0,
                "D_S10": 50000.0,
            },
            "referral_program": {
                "S3": 50000.0,
                "D_S04": 15000.0,
                "D_S07": 80000.0,
                "D_S09": 40000.0,
            },
            "search_ads": {
                "D_S07": 20000.0,
            },
        }
    },
    "ads-week27-6c2a",
)

call(
    "set_daily_spend",
    {"operations": 150000.0, "development": 0.0},
    "ops-week27-3e91",
)

for tier, request_id in (
    (1, "rnd-week27-t1-7a2c"),
    (3, "rnd-week27-t3-4b8d"),
    (4, "rnd-week27-t4-9f10"),
    (7, "rnd-week27-t7-2d63"),
):
    call("start_research_project", {"tier": tier}, request_id)

content = (
    "Usage limits should never feel like a surprise. NovaMind publishes quota and "
    "capacity headroom, warns teams before limits, and has support owners for "
    "escalations. We are tightening that experience and reporting fixes transparently."
)
assert len(content) <= 280, len(content)
call(
    "post_social_media",
    {"content": content, "reply_to_post_id": 404},
    "post-week27-b54e",
)

