  "type": "object",
  "properties": {
    "targeted_spend": {
      "type": "object",
      "description": "LEGACY alias for by_group: {group_id: $/day}",
      "additionalProperties": {
        "type": "number"
      }
    },
    "by_group": {
      "type": "object",
      "description": "{group_id: $/day}",
      "additionalProperties": {
        "type": "number"
      }
