import json
import os
from collections import Counter, defaultdict

import novamind_api as nm
from novamind_api import _client


EXECUTE = os.environ.get("EXECUTE") == "1"
DAY = 203

GROUP_USAGE = {
    "S1": 91.1, "S2": 231.5, "S3": 570.6,
    "D_S01": 86.4, "D_S02": 144.0, "D_S03": 43.2, "D_S04": 248.3,
    "D_S05": 287.9, "D_S06": 108.0, "D_S07": 206.9, "D_S08": 72.0,
    "D_S09": 149.0, "D_S10": 107.8,
    "E1": 52.1, "E2": 222.0, "E3": 137.5,
    "D_E01": 106.5, "D_E02": 93.2, "D_E03": 159.8, "D_E04": 133.2,
    "D_E05": 119.8, "D_E06": 76.9, "D_E07": 173.1, "D_E08": 119.8,
    "D_E09": 79.9, "D_E10": 98.7,
}
TIER_COST = {"A": 0.002, "B": 0.006, "C": 0.012}

TARGET_PRICES = {
    "E1": {"A": 5.0, "B": 10.0, "C": 19.8},
    "E2": {"A": 14.0, "B": 45.0, "C": 88.0},
    "E3": {"A": 25.0, "B": 35.0, "C": 60.0},
    "D_E01": {"A": 60.0, "B": 55.0, "C": 78.0},
    "D_E02": {"A": 15.0, "B": 20.0, "C": 45.0},
    "D_E03": {"A": 70.0, "B": 50.0, "C": 100.0},
    "D_E04": {"A": 50.0, "B": 55.0, "C": 75.0},
    "D_E05": {"A": 30.0, "B": 45.0, "C": 70.0},
    "D_E06": {"A": 25.0, "B": 30.0, "C": 45.0},
    "D_E07": {"A": 50.0, "B": 70.0, "C": 105.0},
    "D_E08": {"A": 40.0, "B": 60.0, "C": 90.0},
    "D_E09": {"A": 40.0, "B": 45.0, "C": 60.0},
    "D_E10": {"A": 10.0, "B": 24.0, "C": 42.0},
}
THIN_MARGIN_GROUPS = {"E1", "E2", "D_E10"}


def rows(sql):
    return nm.query(sql)["rows"]


def floor_price(group, plan, per_seat_usage=None):
    usage = float(GROUP_USAGE[group] if per_seat_usage is None else per_seat_usage)
    return max(1.0, round(usage * 30.0 * TIER_COST[plan] * 1.05, 2))


def normalized_offers(group, offerings):
    answer_by_plan = {}
    for plan, price in offerings:
        if plan not in ("A", "B", "C"):
            continue
        target = TARGET_PRICES[group].get(plan, price)
        floor = floor_price(group, plan)
        normalized = round(max(floor, min(float(price), target)), 2)
        answer_by_plan[plan] = max(answer_by_plan.get(plan, 0.0), normalized)
    answer = [[plan, price] for plan, price in answer_by_plan.items()]
    if not answer:
        answer.append(["A", max(floor_price(group, "A"), TARGET_PRICES[group]["A"])])
    return answer[:3]


latest_threads = rows("""
    WITH latest AS (
        SELECT t.*, ROW_NUMBER() OVER (
            PARTITION BY thread_id ORDER BY turn_number DESC, message_id DESC
        ) AS rn
        FROM enterprise_turns AS t
    )
    SELECT l.customer_id, c.group_id, l.thread_id, l.thread_type, l.turn_number,
           l.day, l.sender, l.seat_count, l.offer_json
    FROM latest AS l JOIN customers AS c ON c.customer_id=l.customer_id
    WHERE l.rn=1 AND l.closed=0
""")

thread_ids = sorted({int(row["thread_id"]) for row in latest_threads})
agent_offers = defaultdict(list)
if thread_ids:
    placeholders = ",".join(str(value) for value in thread_ids)
    for row in rows(f"""
        SELECT thread_id, turn_number, offer_json
        FROM enterprise_turns
        WHERE sender='agent' AND thread_id IN ({placeholders})
        ORDER BY thread_id, turn_number
    """):
        try:
            parsed = json.loads(row["offer_json"] or "[]")
        except json.JSONDecodeError:
            parsed = []
        for offer in parsed:
            if isinstance(offer, dict) and offer.get("plan") in ("A", "B", "C"):
                agent_offers[int(row["thread_id"])].append(
                    (offer["plan"], float(offer["price_per_seat"]))
                )

active_rows = rows(f"""
    SELECT c.customer_id, c.group_id, s.plan, s.effective_price, s.seat_count,
           COALESCE(u.daily_usage, 0) AS daily_usage
    FROM customers AS c
    JOIN subscriptions AS s ON s.customer_id=c.customer_id
    LEFT JOIN (
        SELECT customer_id, SUM(usage_units) / 7.0 AS daily_usage
        FROM daily_usage WHERE day BETWEEN {DAY - 6} AND {DAY}
        GROUP BY customer_id
    ) AS u ON u.customer_id=c.customer_id
    WHERE c.customer_type='large' AND s.status='subscribed' AND s.end_day IS NULL
""")
active = {int(row["customer_id"]): row for row in active_rows}


def current_margin(row):
    return (float(row["seat_count"]) * float(row["effective_price"]) -
            float(row["daily_usage"]) * 30.0 * TIER_COST[row["plan"]])


def per_seat_usage(row):
    if row is None or not row["seat_count"]:
        return None
    return float(row["daily_usage"]) / float(row["seat_count"])


system_deals = []
counter_deals = []
churn_deals = []
renegotiation_deals = []
seen_actionable = set()

for row in latest_threads:
    if row["sender"] == "agent":
        continue
    customer_id = int(row["customer_id"])
    if customer_id in seen_actionable:
        continue
    seen_actionable.add(customer_id)
    group = row["group_id"]
    source = active.get(customer_id)

    if row["thread_type"] == "churn_prevention":
        if source is None:
            continue
        margin = current_margin(source)
        current_price = float(source["effective_price"])
        usage = per_seat_usage(source)
        if margin > 0:
            plan = source["plan"]
            price = max(floor_price(group, plan, usage), current_price * 0.95)
            offerings = [[plan, round(price, 2)]]
            if plan != "A":
                price_a = max(floor_price(group, "A", usage), TARGET_PRICES[group]["A"] * 0.80)
                offerings.append(["A", round(min(price_a, price), 2)])
        else:
            plan = "A"
            price = max(floor_price(group, plan, usage), current_price * 0.80)
            offerings = [[plan, round(price, 2)]]
        churn_deals.append([customer_id, offerings])
        continue

    if row["thread_type"] == "renegotiation" and row["sender"] == "customer":
        try:
            counter = float(json.loads(row["offer_json"] or "{}").get("price", 0))
        except (json.JSONDecodeError, TypeError, ValueError):
            counter = 0.0
        if group in THIN_MARGIN_GROUPS:
            floor_a = floor_price(group, "A", per_seat_usage(source))
            requested = min(TARGET_PRICES[group]["A"], counter) if counter > 0 else TARGET_PRICES[group]["A"]
            offerings = [["A", round(max(floor_a, requested), 2)]]
        else:
            prior = agent_offers[row["thread_id"]] or [("A", TARGET_PRICES[group]["A"])]
            offerings = []
            for plan, prior_price in prior:
                floor = floor_price(group, plan, per_seat_usage(source))
                price = max(floor, min(prior_price, counter if counter > 0 else prior_price))
                offerings.append([plan, round(price, 2)])
        renegotiation_deals.append([customer_id, normalized_offers(group, offerings)])
        continue

    if row["thread_type"] == "new_lead" and row["sender"] == "customer":
        try:
            counter = float(json.loads(row["offer_json"] or "{}").get("price", 0))
        except (json.JSONDecodeError, TypeError, ValueError):
            counter = 0.0
        if group in THIN_MARGIN_GROUPS:
            floor_a = floor_price(group, "A")
            requested = min(TARGET_PRICES[group]["A"], counter) if counter > 0 else TARGET_PRICES[group]["A"]
            offerings = [["A", round(max(floor_a, requested), 2)]]
        else:
            prior = agent_offers[row["thread_id"]] or [
                (plan, TARGET_PRICES[group][plan]) for plan in ("A", "B", "C")
            ]
            offerings = []
            for plan, prior_price in prior:
                floor = floor_price(group, plan)
                price = max(floor, min(prior_price, counter if counter > 0 else prior_price))
                offerings.append([plan, round(price, 2)])
        counter_deals.append([customer_id, normalized_offers(group, offerings)])
        continue

    if row["thread_type"] == "new_lead" and row["sender"] == "system":
        plans = ("A",) if group in THIN_MARGIN_GROUPS else ("A", "B", "C")
        system_deals.append([
            customer_id,
            normalized_offers(group, [(plan, TARGET_PRICES[group][plan]) for plan in plans]),
        ])

batches = {
    "new": (system_deals + counter_deals, "ent-week30-new-0d4e"),
    "churn": (churn_deals, "ent-week30-churn-7b91"),
    "reneg": (renegotiation_deals, "ent-week30-reneg-2f63"),
}

summary = {
    "day": DAY,
    "execute": EXECUTE,
    "latest_threads": len(latest_threads),
    "batches": {
        name: {
            "deals": len(deals),
            "seats": sum(int(row["seat_count"] or 0) for row in latest_threads
                         if int(row["customer_id"]) in {int(deal[0]) for deal in deals}),
            "examples": deals[:3],
            "price_range": [
                min(price for _, offers in deals for _, price in offers),
                max(price for _, offers in deals for _, price in offers),
            ] if deals else None,
        }
        for name, (deals, _) in batches.items()
    },
}
print(json.dumps(summary, indent=2))

if not EXECUTE:
    raise SystemExit(0)

for name, (deals, request_id) in batches.items():
    if not deals:
        continue
    result = _client.call("send_enterprise_deal", {"deals": deals}, request_id=request_id)
    print(request_id, json.dumps(result)[:12000])

