arguments.cmd:
/bin/bash -c "./novamind-operation python-c 'import json,novamind_api as nm; groups=[\"S1\",\"S2\",\"S3\",\"D_S01\",\"D_S02\",\"D_S03\",\"D_S04\",\"D_S05\",\"D_S06\",\"D_S07\",\"D_S08\",\"D_S09\",\"D_S10\"]; out={}; q=lambda s:nm.query(s)[\"rows\"]; active={r[\"group_id\"]:r[\"n\"] for r in q(\"SELECT group_id,COUNT(*) n FROM subscriptions s JOIN customers c ON c.customer_id=s.customer_id WHERE s.status=\\\"subscribed\\\" AND s.end_day IS NULL GROUP BY group_id\")}; 
for g in groups:
 r=nm.market.get_group_insights(g); d=r.get(\"data\",{}); out[g]={\"active\":active.get(g),\"info_level\":d.get(\"info_level\"),\"noise\":d.get(\"noise\"),\"estimates\":d.get(\"estimates\")}
print(json.dumps(out,indent=2))'"

