```json
{
  "type": "object",
  "properties": {
    "global_promotion": {
      "type": "number",
      "description": "Global promotion in $/month for all users. NULL = no change."
    },
    "by_group": {
      "type": "object",
      "description": "Per-group promotion: {group_id: $/month}. Additive with global."
    },
