def floor_price(group, plan, per_seat_usage=None):
    usage = float(GROUP_USAGE[group] if per_seat_usage is None else per_seat_usage)
    return max(1.0, round(usage * 30.0 * TIER_COST[plan] * 1.05, 2))


def normalized_offers(group, offerings):
