    JOIN subscriptions AS s ON s.customer_id=c.customer_id
    LEFT JOIN (
        SELECT customer_id, SUM(usage_units) / 7.0 AS daily_usage
        FROM daily_usage WHERE day BETWEEN {DAY - 6} AND {DAY}
