import glob,json,os
for f in sorted(glob.glob('weekly_status_*.json')):
 d=int(f.split('_')[-1].split('.')[0]); x=json.load(open(f));
 if d<350: continue
 print('\\nDAY',d)
 ads={(a['channel_id'],a['group_id']):a for a in x['ads']}
 arr={(a['group_id'],a['acquisition_source']):a for a in x['arrivals']}
 for k,a in ads.items():
  m=arr.get((k[1],k[0]),{})
  print(f\"{k[1]:5} spend={a['spend']/1000:6.0f}K leads={a['leads']:6d} cpl={a['cpl']:6.2f} active={m.get('active',0):6d} mrr={m.get('mrr',0)/1000:7.1f}K ret={m.get('mrr',0)/a['spend']:5.2f}x\")
PY"

