{
  "/workspace/run-ceobench/act_enterprise_week63.py": {
    "type": "add",
    "content": "import json
import os

import novamind_api as nm
from novamind_api import _client


EXECUTE = os.environ.get("EXECUTE") == "1"
DAY = 434
REQUEST_IDS = {
    "new_lead": "ent-week63-new-8a3c",
    "churn_prevention": "ent-week63-churn-9b4d",
}
TIER_USAGE_COST = {1: 0.0003, 2: 0.002, 3: 0.006, 4: 0.012, 5: 0.03}


def rows(sql):
    return nm.query(sql)["rows"]


config = rows("SELECT tier_A, tier_B FROM config_history ORDER BY day DESC LIMIT 1")[0]
tier_cost = {"A": TIER_USAGE_COST[int(config["tier_A"])],
             "B": TIER_USAGE_COST[int(config["tier_B"])]}

group_usage = {
    row["group_id"]: float(row["per_seat_usage"])
    for row in rows(f"""
        SELECT c.group_id,
               SUM(u.usage_units) / SUM(s.seat_count) / 7.0 AS per_seat_usage
        FROM daily_usage u
        JOIN customers c ON c.customer_id=u.customer_id
        JOIN subscriptions s ON s.customer_id=u.customer_id
         AND s.status='subscribed' AND s.end_day IS NULL
        WHERE c.customer_type='large' AND u.day BETWEEN {DAY - 6} AND {DAY}
        GROUP BY c.group_id
    """)
}

latest = rows(f"""
    WITH latest AS (
        SELECT t.*, ROW_NUMBER() OVER(
            PARTITION BY thread_id ORDER BY turn_number DESC, message_id DESC
        ) AS rn
        FROM enterprise_turns t
    )
    SELECT l.thread_id,l.customer_id,l.thread_type,l.seat_count,l.offer_json,
           c.group_id,s.plan AS current_plan,s.seat_count AS current_seats,
           s.effective_price AS current_price
    FROM latest l
    JOIN customers c ON c.customer_id=l.customer_id
    LEFT JOIN subscriptions s ON s.customer_id=c.customer_id
     AND s.status='subscribed' AND s.end_day IS NULL
    WHERE l.rn=1 AND l.closed=0 AND l.sender='customer'
    ORDER BY l.thread_type DESC,l.seat_count DESC
""")


def floor_price(group, plan):
    usage = group_usage.get(group, 1.0)
    return max(1.0, round(usage * 30.0 * tier_cost[plan] * 1.05, 2))


deals_by_type = {"new_lead": [], "churn_prevention": []}
for row in latest:
    customer_id = int(row["customer_id"])
    group = row["group_id"]
    thread_type = row["thread_type"]
    floor_a = floor_price(group, "A")
    floor_b = floor_price(group, "B")

    if thread_type == "new_lead":
        try:
            counter = float(json.loads(row["offer_json"] or "{}").get("price", 0))
        except (json.JSONDecodeError, TypeError, ValueError):
            counter = 0.0
        deals_by_type[thread_type].append([
            customer_id,
            [["A", floor_a], ["B", max(floor_b, counter)]],
        ])
    elif thread_type == "churn_prevention" and row["current_price"] is not None:
        price_a = max(floor_a, round(float(row["current_price"]) * 0.80, 2))
        deals_by_type[thread_type].append([customer_id, [["A", price_a]]])

planned = {
    "execute": EXECUTE,
    "group_usage": {key: round(value, 3) for key, value in sorted(group_usage.items())},
    "deals_by_type": deals_by_type,
    "counts": {key: len(value) for key, value in deals_by_type.items()},
    "seats": {
        key: sum(int(row["seat_count"] or 0) for row in latest
                  if row["thread_type"] == key)
        for key in deals_by_type
    },
    "request_ids": REQUEST_IDS,
}
print(json.dumps(planned, indent=2))
assert len(latest) == 12
assert len(deals_by_type["new_lead"]) == 8
assert len(deals_by_type["churn_prevention"]) == 4
assert not (set(row["customer_id"] for row in latest) &
            set(row["customer_id"] for row in latest if row["thread_type"] == "other"))

if not EXECUTE:
    raise SystemExit(0)

for thread_type, deals in deals_by_type.items():
    result = _client.call(
        "send_enterprise_deal",
        {"deals": deals},
        request_id=REQUEST_IDS[thread_type],
    )
    print(REQUEST_IDS[thread_type], json.dumps(result)[:6000])
"
  }
}

