{
  "/workspace/run-ceobench/forecast_current.py": {
    "type": "add",
    "content": "import json

import novamind_api as nm


def rows(sql):
    return nm.query(sql)["rows"]


day = int(rows("SELECT MAX(day) AS day FROM ledger")[0]["day"])
cash = float(rows("SELECT SUM(amount) AS cash FROM ledger WHERE day <= :day", {"day": day})[0]["cash"])
config = rows("SELECT * FROM config_history ORDER BY day DESC LIMIT 1")[0]
promotion = json.loads(rows(
    "SELECT settings_json FROM config_overrides "
    "WHERE setting_type='promotion' ORDER BY id DESC LIMIT 1"
)[0]["settings_json"])

group_promotions = promotion.get("by_group", {})
plan_promotions = promotion.get("by_group_plan", {})
listed = {"A": float(config["price_A"]), "B": float(config["price_B"]), "C": float(config["price_C"])}

subs = rows("""
    SELECT c.customer_type, c.group_id, s.plan, s.listed_price,
           s.effective_price, s.seat_count, s.billing_day_mod30
    FROM subscriptions s
    JOIN customers c ON c.customer_id=s.customer_id
    WHERE s.status='subscribed' AND s.end_day IS NULL
""")

buckets = {7: [], 28: [], 45: []}
for sub in subs:
    offset = (int(sub["billing_day_mod30"]) - day % 30 + 30) % 30
    if offset == 0:
        offset = 30
    for horizon in buckets:
        if offset > horizon:
            continue
        if sub["customer_type"] == "large":
            effective = float(sub["effective_price"] or 0.0)
        else:
            group = sub["group_id"]
            plan = sub["plan"]
            discount = float(group_promotions.get(group, 0.0))
            discount += float(plan_promotions.get(group, {}).get(plan, 0.0))
            effective = max(0.0, float(sub["listed_price"]) - discount)
        buckets[horizon].append({
            "type": sub["customer_type"],
            "group": sub["group_id"],
            "plan": sub["plan"],
            "seats": int(sub["seat_count"]),
            "effective": effective,
            "revenue": effective * int(sub["seat_count"]),
        })

summary = {}
for horizon, entries in buckets.items():
    by_group = {}
    for entry in entries:
        key = f"{entry['type']}:{entry['group']}:{entry['plan']}"
        item = by_group.setdefault(key, {"n": 0, "seats": 0, "revenue": 0.0})
        item["n"] += 1
        item["seats"] += entry["seats"]
        item["revenue"] += entry["revenue"]
    summary[horizon] = {
        "scheduled_revenue_100pct": round(sum(v["revenue"] for v in by_group.values()), 2),
        "retail_revenue_100pct": round(sum(v["revenue"] for k, v in by_group.items() if k.startswith("small:")), 2),
        "enterprise_revenue_100pct": round(sum(v["revenue"] for k, v in by_group.items() if k.startswith("large:")), 2),
        "detail": dict(sorted(by_group.items(), key=lambda item: -item[1]["revenue"])),
    }

recent = rows(f"""
    SELECT category, ROUND(SUM(amount), 2) AS amount
    FROM ledger
    WHERE day BETWEEN {day - 6} AND {day}
    GROUP BY category ORDER BY category
""")

print(json.dumps({
    "day": day,
    "cash": cash,
    "config": {
        "prices": listed,
        "capacity_tier": int(config["capacity_tier"]),
        "operations": float(config["spend_operations"]),
        "development": float(config["spend_development"]),
        "advertising": float(config["spend_advertising"]),
    },
    "promotion": promotion,
    "scheduled": summary,
    "recent_week_ledger": recent,
}, indent=2))
"
  }
}

