{
  "type": "object",
  "properties": {
    "A": {
      "type": "integer",
      "description": "Model tier 1-5 for Plan A"
    },
    "B": {
      "type": "integer",
      "description": "Model tier 1-5 for Plan B"
    },
    "C": {
      "type": "integer",
      "description": "Model tier 1-5 for Plan C"
    }
  },
  "required": [
    "A",
    "B",
    "C"
  ]

    "target_level": {
      "type": "integer",
      "description": "Target info level (2-5). If omitted, defaults to current_level + 1."
    }
  },
  "required": [
    "group_id"
  ]
}
